import React, { useState } from "react";
import Tesseract from "tesseract.js";
import API from "./api";
import Navbar from "./Navbar";
import Home from "./Home";
import AboutINS from "./AboutINS";
import AboutSources from "./AboutSources";
import AboutRisk from "./AboutRisk";
import HowItWorks from "./HowItWorks";
import "./style.css";

function App() {
  const [activePage, setActivePage] = useState("home");

  // OCR and Result States
  const [capturedImage, setCapturedImage] = useState("");
  const [ocrText, setOcrText] = useState("");
  const [riskScore, setRiskScore] = useState(0);
  const [riskLevel, setRiskLevel] = useState("Low");
  const [riskReason, setRiskReason] = useState("");
  const [detectedAdditives, setDetectedAdditives] = useState([]);

  // Loading & Error States
  const [loading, setLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");

  const clearScan = () => {
    setCapturedImage("");
    setOcrText("");
    setRiskScore(0);
    setRiskLevel("Low");
    setRiskReason("");
    setDetectedAdditives([]);
    setLoading(false);
    setErrorMessage("");
  };

  const handleCapture = async (imageSrc) => {
    if (!imageSrc) {
      setErrorMessage("Failed to capture image. Please try again.");
      return;
    }

    // Reset previous states but keep current active views
    setCapturedImage(imageSrc);
    setOcrText("");
    setRiskScore(0);
    setRiskLevel("Low");
    setRiskReason("");
    setDetectedAdditives([]);
    setLoading(true);
    setErrorMessage("");

    try {
      console.log("Starting local OCR with Tesseract.js...");
      const result = await Tesseract.recognize(imageSrc, "eng", {
        logger: (m) => console.log(`OCR Progress: ${m.status} - ${Math.round(m.progress * 100)}%`),
      });

      const extractedText = result.data.text;
      console.log("OCR Extracted Text:", extractedText);

      if (!extractedText || extractedText.trim().length === 0) {
        setErrorMessage("No legible text detected. Please ensure the label is in focus, well-lit, and contains text.");
        setOcrText("No text detected.");
        setLoading(false);
        return;
      }

      setOcrText(extractedText);

      console.log("Sending text to backend for additive analysis...");
      const response = await API.post("/analyze", {
        text: extractedText,
      });

      console.log("Backend Response Received:", response.data);

      if (response.data.error) {
        setErrorMessage(`Analysis Error: ${response.data.message}`);
        return;
      }

      const {
        detected_additives,
        overall_risk_score,
        overall_risk_level,
        overall_risk_reason,
      } = response.data;

      setDetectedAdditives(detected_additives || []);
      setRiskScore(overall_risk_score || 0);
      setRiskLevel(overall_risk_level || "Low");
      setRiskReason(overall_risk_reason || "");

      if (!detected_additives || detected_additives.length === 0) {
        setErrorMessage("Analysis completed. No INS additive codes were found in the text.");
      }

    } catch (error) {
      console.error("Pipeline processing failure:", error);
      if (error.code === "ERR_NETWORK" || !error.response) {
        setErrorMessage("Backend server unreachable. Please verify that the Flask server is running on http://127.0.0.1:5000.");
      } else {
        setErrorMessage(`Processing error: ${error.message || error}`);
      }
    } finally {
      setLoading(false);
    }
  };

  const handleCameraError = (errorMsg) => {
    setErrorMessage(errorMsg);
  };

  // State-based router
  const renderActivePage = () => {
    switch (activePage) {
      case "home":
        return (
          <Home
            capturedImage={capturedImage}
            ocrText={ocrText}
            riskScore={riskScore}
            riskLevel={riskLevel}
            riskReason={riskReason}
            detectedAdditives={detectedAdditives}
            loading={loading}
            clearScan={clearScan}
            handleCapture={handleCapture}
            onCameraError={handleCameraError}
          />
        );
      case "about-ins":
        return <AboutINS />;
      case "about-sources":
        return <AboutSources />;
      case "about-risk":
        return <AboutRisk />;
      case "how-it-works":
        return <HowItWorks />;
      default:
        return <Home />;
    }
  };

  return (
    <div className="app dark-theme">
      {/* Navigation Bar */}
      <Navbar activePage={activePage} setActivePage={setActivePage} />

      {/* Global Toast Error / Alert Box */}
      {errorMessage && (
        <div className="error-toast-container">
          <div className="error-toast card glass border-high">
            <div className="error-toast-content">
              <span className="error-icon">⚠️</span>
              <p className="error-message">{errorMessage}</p>
            </div>
            <button className="close-toast-btn" onClick={() => setErrorMessage("")}>
              &times;
            </button>
          </div>
        </div>
      )}

      {/* Main Workspace Page */}
      <main className="main-content">{renderActivePage()}</main>

      {/* Footer */}
      <footer className="main-footer">
        <p>&copy; {new Date().getFullYear()} SAFE BITE Project. All rights reserved.</p>
      </footer>
    </div>
  );
}

export default App;
